/* machine-generated by m2c: a starting point, not a match */
#ifndef M2C_DEFINES
#define M2C_DEFINES
typedef s32 M2C_UNK;
typedef s8 M2C_UNK8;
typedef s16 M2C_UNK16;
typedef s32 M2C_UNK32;
#define M2C_FIELD(expr, type_ptr, offset) (*(type_ptr)((s8 *)(expr) + (offset)))
#define M2C_BITWISE(type, expr) ((type)(expr))
#define M2C_ERROR(desc) (0)
#define M2C_CARRY 0
#define M2C_OVERFLOW(a) (0)
#endif

M2C_UNK stopDistanceSoundWrapper();                            /* extern */
M2C_UNK releaseMusicStream();                            /* extern */
M2C_UNK releaseSoundRequestQueue();                            /* extern */
M2C_UNK shutdownSoundWorker();                            /* extern */

/* Tears down audio: releases the music stream and shuts down the sound worker. */ void stopAllAudio(void) {
    stopDistanceSoundWrapper();
    releaseMusicStream();
    releaseSoundRequestQueue();
    shutdownSoundWorker();
}
